from clip import *
from grounding_dino import post_block

def convnorm(p,id,x,y,cin,cout,k,s,activation='GELU',w=350):
 items=[(f'Conv2d {k}×{k} / {s}',f'{cin} to {cout}, bias=False','conv2d'),('BatchNorm2d',str(cout)+' channels','norm')]
 if activation:items.append((activation,str(cout)+' channels','activation'))
 return chain(p,id,items,x=x,y=y,w=w,gap=85)

